window.BANK = [

// ===================== UNIT 1 =====================
// --- Topic sentence
{id:'u1-ts1',u:1,topic:'Topic sentence',t:'mc',q:'Which is the best topic sentence?',opts:['Food is important.','I ate rice and chicken at 12:30 yesterday.','Eating breakfast provides some benefits for your body.','Breakfast and its benefits.'],a:2,ex:'A çok genel, B çok özel, D ise tam cümle değil, başlık. C hem konu (eating breakfast) hem controlling idea (provides some benefits) içeriyor.'},
{id:'u1-ts2',u:1,topic:'Topic sentence',t:'mc',q:'In "Good sleep improves mental health in some ways." what is the CONTROLLING IDEA?',opts:['Good sleep','improves mental health in some ways','mental health','some ways'],a:1,ex:'Topic = Good sleep. Controlling idea = konu hakkında söylenen özel fikir: improves mental health in some ways.'},
{id:'u1-ts3',u:1,topic:'Topic sentence',t:'mc',q:'In "Using online language apps provides some benefits for prep class students." what is the TOPIC?',opts:['Using online language apps','provides some benefits','prep class students','some benefits for prep class students'],a:0,ex:'Topic = paragrafın neyle ilgili olduğu: Using online language apps.'},
{id:'u1-ts4',u:1,topic:'Topic sentence',t:'mc',q:'Which one can NOT be a topic sentence?',opts:['Cooking at home is healthier for some reasons.','Why is cooking at home healthier?','Cats are ideal pets for busy people for two reasons.','Travelling offers people several important benefits.'],a:1,ex:'Topic sentence soru, başlık, fragment, liste ya da alıntı olamaz. Tam bir bildirme cümlesi olmalı.'},
{id:'u1-ts5',u:1,topic:'Topic sentence',t:'mc',q:'Supporting details: "It saves time between buildings. | It is inexpensive. | It gives students some daily exercise." Best topic sentence?',opts:['Bicycles are popular in many countries.','Using a bicycle on campus has several advantages for students.','I ride my bicycle every day at 8:00.','Bicycles on campus.'],a:1,ex:'Detayların hepsi avantaj: zaman, para, egzersiz. Bu yüzden controlling idea = advantages.'},
{id:'u1-ts6',u:1,topic:'Topic sentence',t:'mc',q:'Paragraph: "First, cats can manage many of their daily needs on their own… Second, adult cats can usually spend several hours alone…" Best topic sentence?',opts:['Cats are ideal pets for busy people for two reasons.','Cats are animals.','Many people have cats and dogs.','Cats clean themselves.'],a:0,ex:'Sunumdaki model cevap. "for two reasons" ifadesi iki major detail\'e (First/Second) uyuyor.'},
{id:'u1-ts7',u:1,topic:'Topic sentence',t:'mc',q:'Paragraph: "First, social media makes direct communication faster and easier… Second, these platforms allow people to share their daily experiences across long distances…" Best topic sentence?',opts:['Social media is bad for teenagers.','Social media helps people stay close to their friends and family in two ways.','Many people use Instagram.','People send messages.'],a:1,ex:'Model cevap. Her iki detay da insanları yakın tutmakla ilgili.'},
{id:'u1-ts8',u:1,topic:'Topic sentence',t:'mc',q:'Paragraph about junk food: risk of serious health problems + replaces healthier meals. Best topic sentence?',opts:['Junk food is delicious.','Eating junk food too often can be harmful to our health.','Fast food restaurants are everywhere.','I like pizza and burgers.'],a:1,ex:'İki detay da sağlığa zararı anlatıyor. Focus word: harmful (problems/disadvantages).'},
{id:'u1-ts9',u:1,topic:'Topic sentence',t:'match',q:'Match each paragraph with its topic sentence.',left:['English is spoken in many countries… travelling easier… study abroad… better job opportunities.','Regular physical activity helps people control their weight… stronger… lower risk of diseases…','The library is usually quieter… useful books… concentrate… ask a librarian…'],right:['Studying in the library can make learning easier.','Learning English opens many doors in life.','Exercise is important for staying healthy.'],a:[1,2,0],ex:'1-b, 2-c, 3-a (sunumdaki cevap anahtarı).'},
{id:'u1-ts10',u:1,topic:'Topic sentence',t:'write',mode:'ts',q:'Write a topic sentence for these details.',info:'Watching English films helps me learn new words. | I can hear the correct pronunciation. | English subtitles help me understand conversations. | I learn useful expressions. | It makes practice enjoyable.',model:['Watching English films helps me improve my English in several ways.'],check:['Tam cümle (özne + fiil), nokta ile bitiyor','Topic: watching English films','Controlling idea: helps improve my English / benefits','Ne çok genel ne çok özel']},
{id:'u1-ts11',u:1,topic:'Topic sentence',t:'write',mode:'ts',q:'Write a topic sentence (Revision 1a).',info:'Studying in the campus garden → Students can get fresh air. | The benches are comfortable. | The quiet area helps them concentrate.',model:['Studying in the campus garden has several benefits for students.','The campus garden is a pleasant and useful place to study.'],check:['Tam cümle','Topic: studying in the campus garden','Controlling idea: benefits / advantages / a good place to study','Detayları listelemedin (liste değil)']},
{id:'u1-ts12',u:1,topic:'Topic sentence',t:'write',mode:'ts',q:'Write a topic sentence (Revision 1c).',info:'A student club → Members meet new people. | They practise useful skills. | They take part in enjoyable activities.',model:['Joining a student club offers students several benefits.','Being a member of a student club has many advantages.'],check:['Tam cümle','Topic: joining a student club','Controlling idea: benefits / advantages']},

// --- Parts of a paragraph
{id:'u1-p1',u:1,topic:'Parts of a paragraph',t:'mc',q:'Which is NOT true about a concluding sentence?',opts:['It comes at the end.','It restates the central idea.','It introduces a new idea to make the paragraph interesting.','It closes the paragraph.'],a:2,ex:'Concluding sentence ASLA yeni fikir getirmez.'},
{id:'u1-p2',u:1,topic:'Parts of a paragraph',t:'mc',q:'"My Hometown" paragraph has 8 sentences. Sentence 1 is the topic sentence and sentence 8 is the concluding sentence. Which sentences are supporting sentences?',opts:['1–2','2–7','2–8','3–6'],a:1,ex:'Supporting sentences ortada yer alır: 2–7.'},
{id:'u1-p3',u:1,topic:'Parts of a paragraph',t:'mc',q:'"To sum up, the British Museum\'s collections, tours, and beautiful building make it a wonderful place to visit." This sentence is…',opts:['T (topic)','SS (supporting)','C (concluding)'],a:2,ex:'"To sum up" concluding signal. Ana noktaları özetliyor.'},
{id:'u1-p4',u:1,topic:'Parts of a paragraph',t:'mc',q:'"The British Museum in London offers visitors an interesting day out." This sentence is…',opts:['T (topic)','SS (supporting)','C (concluding)'],a:0,ex:'Konuyu ve controlling idea\'yı (interesting day out) veren cümle.'},
{id:'u1-p5',u:1,topic:'Parts of a paragraph',t:'mc',q:'The shopping mall paragraph has a topic sentence, 3 major details each with 1 minor detail, and a concluding sentence. How many supporting sentences?',opts:['three','four','six','eight'],a:2,ex:'3 major + 3 minor = 6 supporting sentences.'},
{id:'u1-p6',u:1,topic:'Parts of a paragraph',t:'match',q:'My Campus: match the sentence number with its function. "(1) My university campus is an enjoyable place to spend free time. (2) First, it has several green areas… (3) Students can relax… (4) Second, there are many cafés… (5) Students often meet there… (6) In addition, the student centre offers… (7) For example, students can participate in clubs… (8) In short, my campus is a lively place…"',left:['Tells the reader the main idea','Introduces the first place','Explains what students do at the cafés','Gives examples of activities at the student centre','Summarises the main idea and closes'],right:['1','2','3','4','5','6','7','8'],a:[0,1,4,6,7],ex:'Main idea = 1, first place = 2, cafés explanation = 5, examples = 7, close = 8. (Ayrıca: second place = 4, another place = 6, green areas = 3.)'},

// --- Major / minor
{id:'u1-m1',u:1,topic:'Major & minor',t:'mc',q:'TS: Hyde Park offers several enjoyable ways to spend time outdoors. "Hyde Park is an excellent place for a picnic with family or friends." is a…',opts:['Major detail','Minor detail'],a:0,ex:'Topic sentence\'ı doğrudan destekleyen ana nokta (picnic). Bunu açıklayan cümle minor olur.'},
{id:'u1-m2',u:1,topic:'Major & minor',t:'mc',q:'TS: Hyde Park offers several enjoyable ways… "Adults can play tennis or hire a boat, while children can have fun in the playground." is a…',opts:['Major detail','Minor detail'],a:1,ex:'"The park provides various activities…" major\'ının örnekleri, yani minor.'},
{id:'u1-m3',u:1,topic:'Major & minor',t:'mc',q:'TS: Hyde Park… "Visitors can walk beside the Serpentine Lake, watch wildlife, or rest on the green grass." is a…',opts:['Major detail','Minor detail'],a:1,ex:'"Peaceful natural environment" major\'ının somut örnekleri, yani minor.'},
{id:'u1-m4',u:1,topic:'Major & minor',t:'match',q:'TS: The Alps are a great place for a holiday. Match major with minor.',left:['The natural scenery is beautiful.','Visitors can enjoy many outdoor activities.','There are delicious local foods to try.'],right:['Visitors can ski in winter and go hiking in summer.','Visitors can try local cheese, warm soups, and fresh bread.','Snowy mountain peaks, green valleys, and clear blue lakes offer wonderful views.'],a:[2,0,1],ex:'1-c, 2-a, 3-b'},
{id:'u1-m5',u:1,topic:'Major & minor',t:'match',q:'TS: Getting enough sleep can help university students study more effectively. (Revision 2a)',left:['Enough sleep can improve students\' concentration.','Good sleep can help students remember information.','Enough sleep can support students\' emotional wellbeing.'],right:['Students may feel calmer and less stressed after a good night\'s sleep.','Well-rested students can pay attention to a lecture for longer.','Students may find it easier to remember information they studied the day before.'],a:[1,2,0],ex:'1-b (concentration ↔ pay attention), 2-c (remember ↔ remember), 3-a (wellbeing ↔ calmer, less stressed).'},
{id:'u1-m6',u:1,topic:'Major & minor',t:'write',mode:'minor',q:'Add ONE new minor detail (Revision 2b).',info:'Major detail: Enough sleep can help students feel more energetic during the day.',model:['For example, well-rested students do not feel sleepy in their morning classes.','For instance, they have enough energy to go to the gym or join club activities after lessons.'],check:['Major detail\'ı açıklıyor (energy)','Somut örnek ya da fact','For example / For instance ile başlıyor (önerilir)','Tam cümle']},
{id:'u1-m7',u:1,topic:'Major & minor',t:'write',mode:'minor',q:'Write the missing MINOR detail.',info:'TS: The campus cafeteria is a good choice for lunch. | Major: It offers different types of food.',model:['Students can choose soup, salads, pasta, or a hot daily menu.'],check:['Major\'ı örnekliyor (types of food)','Tam cümle','Yeni bir ana fikir değil']},
{id:'u1-m8',u:1,topic:'Major & minor',t:'write',mode:'minor',q:'Write the missing MAJOR detail.',info:'TS: Staying at a hotel can make a holiday more relaxing. | Minor: Hotel staff clean the room, make the bed, and provide fresh towels.',model:['Guests do not have to do any housework.'],check:['Minor\'ı kapsayan genel nokta','Topic sentence\'ı doğrudan destekliyor','Tam cümle']},
{id:'u1-m9',u:1,topic:'Major & minor',t:'write',mode:'minor',q:'Write the missing MAJOR detail.',info:'TS: Renting a car can make travelling on holiday more convenient. | Minor: Travellers can leave at any time and stop whenever they need a break.',model:['Travellers can follow their own schedule.'],check:['Genel nokta (major)','Minor ile uyumlu']},

// --- Signalling
{id:'u1-s1',u:1,topic:'Signalling words',t:'mc',q:'"For example, For instance, To illustrate, such as" — function?',opts:['Adding a major detail','Introducing an example','Showing a result','Concluding'],a:1,ex:'Örnek verme.'},
{id:'u1-s2',u:1,topic:'Signalling words',t:'mc',q:'"As a result, Therefore, Because of this, Consequently, That is why" — function?',opts:['Showing a result or effect','Introducing an example','Adding a further point','Opening the paragraph'],a:0,ex:'Sonuç/etki.'},
{id:'u1-s3',u:1,topic:'Signalling words',t:'mc',q:'"Moreover, Furthermore, In fact" — function?',opts:['Showing a result','Adding a further point','Introducing an example','Concluding'],a:1,ex:'Ek nokta ekleme.'},
{id:'u1-s4',u:1,topic:'Signalling words',t:'gap',q:'The Campus Cafeteria — use each word once.',text:'The campus cafeteria is a good choice for lunch. {0}, it offers different types of food. {1}, students can choose soup, sandwiches, or a hot daily menu. {2}, the prices are reasonable for students on a limited budget. {3}, many students save money by eating there instead of buying lunch outside campus. {4}, the cafeteria is close to most departments, so students do not lose much time between classes. {5}, some students meet their friends there between lessons.',bank:['First','For example','In addition','As a result','Also','In fact'],a:['First','For example','In addition','As a result','Also','In fact'],ex:'First (1. major) → For example (örnek) → In addition (2. major) → As a result (sonuç: para tasarrufu) → Also (3. major) → In fact (ek nokta).'},
{id:'u1-s5',u:1,topic:'Signalling words',t:'gap',q:'Studying with Classmates — choose the best option.',text:'Studying with classmates can be helpful in several ways. {0}, students can discuss difficult topics together. {1}, if a student does not understand a maths problem, another student can explain it. {2}, students can share their notes and study materials. This gives everyone more information to study. {3}, students may understand the course content better. {4}, studying together can make exam preparation less stressful. {5}, many students feel more motivated when they study with other people.',bank:['First','Also','For example','Furthermore','In addition','As a result','For instance','In fact'],a:['First','For example','In addition','As a result','Furthermore','In fact'],ex:'First / For example / In addition / As a result / Furthermore / In fact (cevap anahtarı).'},
{id:'u1-s6',u:1,topic:'Signalling words',t:'mc',q:'Which sentence uses "such as" correctly?',opts:['Such as, students can play football.','Students can play many sports, such as football and tennis.','Students can play sports. Such as football.','Such as football, is popular.'],a:1,ex:'"such as" + isim, cümlenin içinde kullanılır. Cümle başında virgülle gelmez ve tek başına cümle olamaz.'},
{id:'u1-s7',u:1,topic:'Signalling words',t:'mc',q:'Which tip about signalling words is TRUE (teacher\'s tip)?',opts:['Every sentence must start with a signalling word.','Use them mainly when you begin a new major detail or introduce an example.','Never use them in the concluding sentence.','Use "For example" for major details.'],a:1,ex:'Çok fazla kullanmak paragrafı mekanik yapar.'},

// --- Concluding
{id:'u1-c1',u:1,topic:'Concluding sentence',t:'mc',q:'TS: Online learning has several important advantages. Best concluding sentence?',opts:['Online learning has several important advantages.','Overall, online learning offers students many useful benefits.','Also, online classes are cheaper than taxis.','In conclusion, many teachers use Zoom and Teams in 2020.'],a:1,ex:'A kopya, C yeni detay, D yeni bilgi. B ise farklı kelimelerle tekrar ediyor.'},
{id:'u1-c2',u:1,topic:'Concluding sentence',t:'mc',q:'TS: Exercise has many benefits for the body. "Therefore, I strongly encourage you to start exercising every day." This conclusion…',opts:['restates','gives a final thought','gives a recommendation','adds a new idea'],a:2,ex:'Tavsiye (recommend).'},
{id:'u1-c3',u:1,topic:'Concluding sentence',t:'mc',q:'Which is NOT a concluding signal?',opts:['In short,','For these reasons,','For instance,','All in all,'],a:2,ex:'For instance örnek verir.'},
{id:'u1-c4',u:1,topic:'Concluding sentence',t:'write',mode:'concl',q:'Write a concluding sentence. Begin with a concluding signal.',info:'TS: My city has many interesting places to visit.',model:['In conclusion, my city is full of exciting places that every visitor should see.'],check:['Concluding signal ile başlıyor','Ana fikri FARKLI kelimelerle söylüyor','Yeni bilgi yok','Topic sentence\'ın kopyası değil']},
{id:'u1-c5',u:1,topic:'Concluding sentence',t:'write',mode:'concl',q:'Write a concluding sentence.',info:'TS: Coffee is one of the most popular drinks in the world.',model:['To sum up, coffee is a drink that people all over the world enjoy every day.'],check:['Signal var','Farklı kelimeler','Yeni bilgi yok']},
{id:'u1-c6',u:1,topic:'Concluding sentence',t:'write',mode:'concl',q:'Write a concluding sentence for the paragraph.',info:'City life offers many advantages. First, cities provide more job opportunities… In addition, cities usually have better schools and more entertainment options… Public transport also makes it easy to get around.',model:['For these reasons, many people prefer to live in a big city.'],check:['Signal var','Paragrafı kapatıyor','Yeni fikir yok']},
{id:'u1-c7',u:1,topic:'Concluding sentence',t:'write',mode:'concl',q:'Write a concluding sentence.',info:'TS: Having a hobby is important for your wellbeing.',model:['For these reasons, everyone should find a hobby they enjoy.'],check:['Signal var','Restate / final thought / recommend','Yeni bilgi yok']},

// --- Reference words
{id:'u1-r1',u:1,topic:'Reference words',t:'mc',q:'"Mert and his classmates are preparing a presentation… They meet every Tuesday… Mert prepares the slides and shares them with the group." — "them" refers to…',opts:['Mert and his classmates','the slides','the group','Tuesdays'],a:1,ex:'shares them = shares the slides.'},
{id:'u1-r2',u:1,topic:'Reference words',t:'mc',q:'Same text: "They meet every Tuesday" — "They" refers to…',opts:['the slides','Mert and his classmates','the teachers','the projects'],a:1,ex:'Toplanan kişiler: Mert and his classmates.'},
{id:'u1-r3',u:1,topic:'Reference words',t:'mc',q:'"The Sydney Opera House… is especially known for its unusual roof and white shell-like structures. Architecture students often study these…" — "these" refers to…',opts:['architecture students','its unusual roof and white shell-like structures','modern buildings','the harbour'],a:1,ex:'these = its unusual roof and white shell-like structures.'},
{id:'u1-r4',u:1,topic:'Reference words',t:'mc',q:'"Professor Maya Demir… asks university students about their sleeping habits and gives them a short attention test." — "them" =',opts:['Professor Maya Demir','sleeping habits','(the) university students','the results'],a:2,ex:'Testi verdiği kişiler: university students.'},
{id:'u1-r5',u:1,topic:'Reference words',t:'mc',q:'Revision 4: "(6) Finally, students can buy drinks from the café downstairs. (7) They can take them to the study area while they work." — "They" and "them" =',opts:['They = drinks, them = students','They = students, them = drinks','They = cafés, them = tables','They = tables, them = laptops'],a:1,ex:'They = students, them = drinks.'},
{id:'u1-r6',u:1,topic:'Reference words',t:'write',mode:'ref',q:'Rewrite using reference words.',info:'Sarah is a nurse. Sarah works at a hospital. Sarah helps many patients every day. Sarah likes the hospital because the hospital is clean and quiet. Sarah wants to work in a big city hospital one day.',model:['Sarah is a nurse. She works at a hospital. She helps many patients every day. She likes the hospital because it is clean and quiet. She wants to work in a big city hospital one day.'],check:['Sarah → She','the hospital (2.) → it','Anlam değişmedi','İlk cümlede isim duruyor (Sarah)']},
{id:'u1-r7',u:1,topic:'Reference words',t:'write',mode:'ref',q:'Rewrite using reference words.',info:'Social media is popular with young people. Social media lets people share photos and videos. Social media also helps people stay in touch with friends. Many people use social media every day. Social media can be fun, but social media can also be stressful.',model:['Social media is popular with young people. It lets people share photos and videos. It also helps them stay in touch with friends. Many people use it every day. It can be fun, but it can also be stressful.'],check:['Social media → It / it','people → them','İlk cümlede isim duruyor']},
{id:'u1-r8',u:1,topic:'Reference words',t:'mc',q:'Which version is better and why? A: "Mark… He travels… His job allows him…" B: "Mark… Mark travels… Mark\'s job allows Mark…"',opts:['B, because names are clearer','A, because it uses reference words instead of repeating the noun','Both are the same','B, because it is longer'],a:1,ex:'Reference words akıcılık sağlar.'},

// --- Unity
{id:'u1-un1',u:1,topic:'Paragraph unity',t:'mc',q:'(1) Studying animals can help bioengineers develop useful new products. (2) First, bioengineers can study how animals move to design better machines. (3) For example, birds and insects give ideas for small flying robots. (4) Some bioengineers work with doctors and other scientists in research laboratories. (5) Bioengineers can also study the special surfaces of animals to develop new materials. (6) For instance, shark skin… (7) For these reasons… — Irrelevant sentence?',opts:['2','3','4','5'],a:2,ex:'4 bioengineer\'ların nerede çalıştığından bahsediyor, hayvanlardan öğrenmeyle ilgili değil.'},
{id:'u1-un2',u:1,topic:'Paragraph unity',t:'mc',q:'(1) A small local business can be managed successfully by following a few important practices. (2) First, owners need to understand what their customers want. (3) They can talk to customers… (4) In addition, small business owners need to manage their money carefully. (5) For example, they should regularly check their costs… (6) Large international companies also have to make plans to adjust their budgets. (7) These practices… — Irrelevant?',opts:['3','5','6','7'],a:2,ex:'6 büyük uluslararası şirketlerden bahsediyor. Konu küçük yerel işletmeler.'},
{id:'u1-un3',u:1,topic:'Paragraph unity',t:'mc',q:'(1) A good language learner usually has several important qualities. (2) First, a good language learner is willing to practise regularly. (3) For example, they review new vocabulary… (4) Learning English is several online apps. (5) Another important quality is being willing to learn from mistakes. (6) Good language learners notice their errors… (7) These qualities… — Irrelevant?',opts:['2','4','5','6'],a:1,ex:'4 iyi öğrencinin nitelikleriyle ilgili değil.'},
{id:'u1-un4',u:1,topic:'Paragraph unity',t:'mc',q:'Revision 4 — A Good Place to Study: (1) The student centre is a convenient place to study between classes. (2) First, it has several quiet tables on the second floor. (3) Students can use the tables for laptops, books, and notes. (4) In addition, it has free Wi-Fi. (5) The student centre also has a small music room for band practice. (6) Finally, students can buy drinks from the café downstairs. (7) They can take them to the study area. (8) For these reasons… — Irrelevant?',opts:['3','5','6','7'],a:1,ex:'Müzik odası ders çalışmayla ilgili değil.'},
{id:'u1-un5',u:1,topic:'Paragraph unity',t:'mc',q:'Profile: "A good place to relax on campus — campus garden: trees and grass; benches; quiet corners; close to the cafeteria; students sometimes play football nearby." Which idea should you LEAVE OUT?',opts:['benches','quiet corners','students sometimes play football nearby','close to the cafeteria'],a:2,ex:'Futbol gürültü yapar, bu da "relax / quiet" fikrini zayıflatır. Revizyon özellikle bunu soruyor.'},
{id:'u1-un6',u:1,topic:'Paragraph unity',t:'mc',q:'Jamie\'s Moon Café first draft (message: a good place to study). Which details are unnecessary?',opts:['the sockets and the laptop','the opening date and the homemade cakes','the quiet atmosphere','the friendly staff'],a:1,ex:'Hocanın notu: "The opening date and cakes: do these details help your message?"'},
{id:'u1-un7',u:1,topic:'Paragraph unity',t:'mc',q:'Moon Café: which sentence can be ADDED to support "a good place to study"?',opts:['It also has free Wi-Fi, so I can research my assignments online.','It often gets very noisy, so I cannot concentrate.','It usually closes quite early, so I prefer the library.'],a:0,ex:'Sadece a mesajı destekliyor.'},

// --- Grammar from feedback
{id:'u1-g1',u:1,topic:'Sentence structure',t:'mc',q:'Which is a complete sentence?',opts:['Because the café is quiet and I can concentrate.','The tables are large, and the chairs quite comfortable.','I go there in the afternoons because it is quiet.','The café also sell homemade cakes.'],a:2,ex:'A fragment, B fiil eksik (are), D özne-fiil uyumsuz (sells).'},
{id:'u1-g2',u:1,topic:'Sentence structure',t:'mc',q:'Correct the error: "The café also sell delicious cakes."',opts:['The café also selling delicious cakes.','The café also sells delicious cakes.','The café also are sell delicious cakes.','The café sold also cakes.'],a:1,ex:'Tekil özne + present simple → -s.'},

// --- Planning / writing
{id:'u1-w1',u:1,topic:'Paragraph writing',t:'write',mode:'parts-idea',q:'Revision 3: Write each missing part (Living near campus).',info:'a. TS — Topic: Living near campus | Controlling idea: advantages for university students<br>b. Major 1 + minor — save travel time | walk to class in about ten minutes<br>c. Major 2 + minor — easy access to campus facilities | library and sports centre are nearby<br>d. Major 3 + minor — easier to meet classmates | group members can meet on campus after lessons<br>e. Concluding — restate in different words; no new idea',model:['a. Living near campus has several advantages for university students.\nb. First, students can save a lot of travel time. For example, they can walk to class in about ten minutes.\nc. In addition, they have easy access to campus facilities. For instance, the library and the sports centre are nearby.\nd. Finally, it is easier for students to meet their classmates. Group members can meet on campus after lessons.\ne. For these reasons, choosing accommodation close to the university can make student life much more convenient.'],check:['a: topic + controlling idea (advantages)','b–d: major + minor ayrı iki cümle','Her major signalling word ile (First / In addition / Finally)','Minor\'lar verilen fact\'i kullanıyor','e: concluding signal + farklı kelimeler + yeni fikir yok','Reference words (they / it) kullanıldı']},
{id:'u1-w2',u:1,topic:'Paragraph writing',t:'write',mode:'para-idea',q:'Revision 6: Write the paragraph "A Good Place to Relax on Campus" (7–9 sentences, ONE paragraph).',info:'Campus garden — trees and grass; benches; quiet corners; close to the cafeteria; <s>students sometimes play football nearby</s> | Facts: sit under the trees; read or talk with friends; rest between classes; buy a drink nearby | Central idea: a comfortable and convenient place to relax between classes',model:['The campus garden is a comfortable and convenient place to relax between classes. First, it has a lot of tall trees and soft green grass. For example, students can sit in the shade of the trees on hot days. In addition, there are many benches and quiet corners in the garden. Students can read a book or talk with their friends there without any noise. Finally, the garden is very close to the cafeteria. They can buy a drink nearby and rest before their next lesson. For these reasons, the campus garden is the perfect spot for students to take a break during a busy day.'],check:['TS: topic + controlling idea','3 major detail (First / In addition / Finally)','Her major\'ın minor detail\'i var (fact/example)','Futbol fikri KULLANILMADI (unity)','Signalling words var ama her cümlede değil','Reference words (it / they / there)','Concluding: farklı kelimelerle, yeni fikir yok','7–9 cümle, TEK paragraf','Büyük harf, noktalama, yazım']},
{id:'u1-w3',u:1,topic:'Paragraph writing',t:'write',mode:'para-idea',q:'Unit Task: Write a paragraph (6–8 sentences): "A restaurant you would recommend to a friend".',info:'Plan: TS (topic + controlling idea) → 2–3 major + minor → concluding (don\'t copy TS).',model:['Lezzet Kebab near our campus is a restaurant I would recommend to any friend. First, the food is delicious and fresh. For example, the chef cooks the meat on a real charcoal grill every evening. In addition, the prices are reasonable for students. A full meal with a drink costs less than two hundred liras there. Finally, the staff are friendly and the service is fast. For these reasons, I always tell my friends to try this restaurant when they want a tasty and affordable meal.'],check:['TS: topic + controlling idea','≥2 major + minor','Signalling words','Reference words','Concluding sentence (kopya değil)','6–8 cümle','Yazım/noktalama']},
{id:'u1-w4',u:1,topic:'Paragraph writing',t:'write',mode:'major-minor',q:'Exercise 7: Write two major sentences and support each with a minor detail.',info:'TS: Living close to campus offers several advantages for university students. | CS: In conclusion, choosing accommodation near campus can make student life much more convenient.',model:['Major I: First, students can walk to their classes, so they save a lot of time.\nMinor I: For example, they do not need to wait for buses or sit in traffic every morning.\nMajor II: In addition, living near campus helps students save money.\nMinor II: They do not have to pay for buses or taxis every day.'],check:['2 major (signalling ile)','Her major\'a 1 minor','Hepsi advantages fikrini destekliyor']},

// ===================== UNIT 2 =====================
{id:'u2-ts1',u:2,topic:'Topic sentence',t:'mc',q:'Which is the best topic sentence for an instruction paragraph?',opts:['Writing a lab report.','You should write a lab report.','You can write a clear lab report in a few simple steps.','Lab reports are boring.'],a:2,ex:'Görevi tanıtıyor + adımların geleceğini gösteriyor. A tam cümle değil (hocanın düzelttiği hata).'},
{id:'u2-ts2',u:2,topic:'Topic sentence',t:'mc',q:'"Organizing a birthday party requires careful planning." — controlling idea?',opts:['Organizing a birthday party','requires careful planning','a birthday party','planning'],a:1,ex:'Topic = Organizing a birthday party; controlling idea = requires careful planning.'},
{id:'u2-ts3',u:2,topic:'Topic sentence',t:'mc',q:'Which word is NOT a typical controlling idea focus word for instructions?',opts:['steps','methods','techniques','reasons'],a:3,ex:'reasons = cause paragraph (Unit 1). Instructions: steps, methods, plan, instructions, ways, techniques, preparation.'},
{id:'u2-ts4',u:2,topic:'Topic sentence',t:'mc',q:'Which sentence uses -ing correctly as a subject?',opts:['Give a presentation is easier when you prepare.','Giving a presentation is easier when you prepare carefully.','To giving a presentation is easy.','Gave a presentation is easy.'],a:1,ex:'Fiil özne olacaksa -ing alır.'},
{id:'u2-ts5',u:2,topic:'Topic sentence',t:'write',mode:'ts-instr',q:'Write a topic sentence: How to connect to Wi-Fi on the AGÜ campus.',info:'',model:['Connecting to Wi-Fi on the AGÜ campus is easy if you follow a few simple steps.'],check:['Görev (task) var','Steps/instructions fikri var','Tam cümle']},
{id:'u2-ts6',u:2,topic:'Topic sentence',t:'write',mode:'ts-instr',q:'Write a topic sentence: How to open a student bank account online.',info:'',model:['You can open a student bank account online in a few easy steps.'],check:['Task + steps','Tam cümle']},
{id:'u2-ts7',u:2,topic:'Topic sentence',t:'write',mode:'ts-instr',q:'Revision 3a: Task: join a university club online | Focus: a few simple steps',info:'',model:['You can join a university club online in a few simple steps.','Joining a university club online is easy if you follow a few simple steps.'],check:['Task: join a university club online','Focus: a few simple steps','Tam cümle']},
{id:'u2-ts8',u:2,topic:'Topic sentence',t:'write',mode:'ts-instr',q:'Write a topic sentence for the paragraph.',info:'(1) First, choose a password with at least eight characters. (2) A longer password is more difficult to guess. (3) Next, use a mix of capital letters, small letters, and numbers… (5) Then, add a symbol, such as # or @…',model:['You can create a strong password by following a few simple steps.'],check:['Topic: creating a strong password','Steps','Tam cümle']},

// imperatives
{id:'u2-i1',u:2,topic:'Imperatives',t:'mc',q:'Change into an imperative: "You should not smoke here."',opts:['You do not smoke here.','Do not smoke here.','Not smoke here.','Smoking not here.'],a:1,ex:'Negative: Do not / Don\'t + base verb.'},
{id:'u2-i2',u:2,topic:'Imperatives',t:'mc',q:'Change into an imperative: "Staff have to wash their hands carefully."',opts:['Staff wash hands carefully.','Wash your hands carefully.','You have to wash your hands.','Washing your hands carefully.'],a:1,ex:'Özne yok, base verb ile başla.'},
{id:'u2-i3',u:2,topic:'Imperatives',t:'mc',q:'Rule: In instructions, we start the sentence with the ____ form of the verb and we don\'t use a ____.',opts:['past / object','base / subject','-ing / verb','-ed / subject'],a:1,ex:'base form · no subject (I, you, we…).'},
{id:'u2-i4',u:2,topic:'Imperatives',t:'mc',q:'Which step is written correctly?',opts:['You should write the title first.','You write the aim of the experiment.','First, write the title of your experiment.','Writing the title first.'],a:2,ex:'Sequence word + imperative.'},
{id:'u2-i5',u:2,topic:'Imperatives',t:'write',mode:'imp',q:'Revision 2a: Turn the notes into imperative instructions (write 4 sentences).',info:'you should log in with your student account | you should open the document you want to print | you must not choose the wrong printer | you should check the number of pages',model:['Log in with your student account. Open the document you want to print. Do not choose the wrong printer. Check the number of pages.'],check:['"you should/must" YOK','Base verb ile başlıyor','Negatif: Do not / Don\'t','Büyük harf + nokta']},
{id:'u2-i6',u:2,topic:'Imperatives',t:'write',mode:'imp',q:'Change into imperatives.',info:'1. You should add the water slowly. 2. You must not run.',model:['Add the water slowly. Do not run.'],check:['Özne yok','Base form','Do not + V1']},
{id:'u2-i7',u:2,topic:'Imperatives',t:'match',q:'Match each instruction with the situation.',left:['Apply a small amount to clean, dry skin.','Choose a program and press start.','Do not use the elevator in case of fire.','Preheat the oven to 180°C.','Insert your card and enter your PIN.'],right:['oven / baking','skin cream','ATM','washing machine','fire safety sign'],a:[1,3,4,0,2],ex:'Krem, çamaşır makinesi, yangın, fırın, ATM.'},

// improve weak instructions
{id:'u2-im1',u:2,topic:'Useful details',t:'write',mode:'imp',q:'Revision 1: Improve each weak instruction with the useful information.',info:'Open the page. → course page → Assignments section<br>Choose the file. → PDF named WRIT100_Task2_NameSurname<br>Upload it. → click Attach File → select the PDF<br>Check it. → open the attached file; make sure it is the correct version<br>Send it. → click Submit; wait for the confirmation message',model:['Open the course page and go to the Assignments section. Choose the PDF file named WRIT100_Task2_NameSurname. Click "Attach File" and select the PDF. Open the attached file and make sure it is the correct version. Click "Submit" and wait for the confirmation message.\n\nWarning / check: Make sure you attach the correct version before you click Submit. / Do not close the page before you see the confirmation message.'],check:['Her adım imperative','Verilen detaylar (which page, which file, which button) eklendi','Buton adları tırnak içinde (isteğe bağlı)','Bir warning/check yazıldı (Make sure… / Do not…)']},
{id:'u2-d1',u:2,topic:'Useful details',t:'mc',q:'Which instruction is MOST useful for the reader?',opts:['Put some tea in the pot.','Put two or three teaspoons of black tea leaves into the small top pot.','Put tea.','Add the tea and wait.'],a:1,ex:'how much (two or three teaspoons) + which (black tea leaves) + where (small top pot).'},
{id:'u2-d2',u:2,topic:'Useful details',t:'mc',q:'Useful details answer which questions?',opts:['who / why','how much / how long / where / which file or button','when did it happen / who was there','what is your opinion'],a:1,ex:'Revizyon kutusu: how much / how long / where / which file or button.'},

// warnings
{id:'u2-w1',u:2,topic:'Warnings',t:'mc',q:'Situation: Several printers have similar names, so a student may send the document to another building. Best warning?',opts:['Finally, collect your pages.','Make sure you choose the printer in your building before you click Print.','Printers are expensive.','You should print.'],a:1,ex:'Uyarı hatayı önlemeli, bu yüzden sorunun kendisine (yanlış yazıcı) yönelik olmalı.'},
{id:'u2-w2',u:2,topic:'Warnings',t:'mc',q:'Using a public ATM — best warning?',opts:['Remember to apply it again every two hours.','Make sure nobody can see your PIN.','Be careful with the acid.','Don\'t forget to lock the windows.'],a:1,ex:'Model cevap.'},
{id:'u2-w3',u:2,topic:'Warnings',t:'write',mode:'warn',q:'Write a warning.',info:'You are using a sharp kitchen knife.',model:['Be careful with the knife and keep your fingers away from the blade.'],check:['Warning ifadesi (Be careful / Make sure / Do not / Remember to / Don\'t forget to)','Durumla ilgili','Imperative']},
{id:'u2-w4',u:2,topic:'Warnings',t:'write',mode:'warn',q:'Write a warning.',info:'You are leaving your house for a long trip.',model:['Don\'t forget to lock all the doors and windows.'],check:['Warning ifadesi','Durumla ilgili']},
{id:'u2-w5',u:2,topic:'Warnings',t:'write',mode:'warn',q:'Write a warning.',info:'You are preparing an assignment and the deadline is close.',model:['Make sure you submit your assignment on time.'],check:['Warning ifadesi','Durumla ilgili']},
{id:'u2-w6',u:2,topic:'Warnings',t:'write',mode:'warn',q:'Complete the paragraph with a warning.',info:'Storing your medicine correctly is important for your health. First, keep the medicine in its original box or bottle. Next, put it in a cool, dry place, such as a cupboard. ________ This will keep the medicine safe and effective.',model:['Do not expose the medicine to sunlight.','Make sure the place is not too hot.'],check:['Warning ifadesi','Konuyla ilgili (heat/sun/children)']},
{id:'u2-w7',u:2,topic:'Warnings',t:'mc',q:'Revision 1: Which instruction most needs a warning or final check?',opts:['Open the page.','Choose the file.','Check it / Send it — make sure it is the correct version before submitting','None'],a:2,ex:'Yanlış versiyonu göndermek geri alınamaz, bu yüzden göndermeden önce kontrol uyarısı gerekir.'},

// order / sequence
{id:'u2-o1',u:2,topic:'Sequence',t:'order',q:'Revision 2b: Put the printing steps in order.',items:['Open the document on the campus computer.','Choose Print from the document menu.','Check the printer name and number of copies.','Click Print and wait for the job to finish.','Collect your pages from the printer.'],ex:'Open → Choose Print → Check → Click Print → Collect.'},
{id:'u2-o2',u:2,topic:'Sequence',t:'order',q:'Organise course files — order the steps.',items:['Create a folder called "My Courses" on your computer.','Create a separate folder for each course inside "My Courses".','Move your files into the correct course folders.','Check that all your files are in the right place.'],ex:'1 Create My Courses → 2 Create course folders → 3 Move files → 4 Check.'},
{id:'u2-o3',u:2,topic:'Sequence',t:'order',q:'Photocopier diagram — order the steps.',items:['Tap your student card.','Select "Copy".','Place your document on the glass.','Choose the settings (copies, colour).','Press "Start".'],ex:'Diyagram sırası 1–5.'},
{id:'u2-o4',u:2,topic:'Sequence',t:'order',q:'Make Turkish tea — order.',items:['Boil water in the bottom pot.','Put two or three teaspoons of tea into the top pot.','Pour a little boiling water onto the tea leaves.','Add more water to the bottom pot and place the top pot on it.','Let the tea brew for 10–15 minutes.','Pour the tea into a glass.'],ex:'boil → put tea → pour water → add water → brew → serve.'},
{id:'u2-o5',u:2,topic:'Sequence',t:'order',q:'Plant a tree — order.',items:['Dig a hole about 30 cm deep with a spade.','Put the sapling in the middle of the hole.','Fill the hole with soil and organic compost.','Water the tree with a watering can.','Tie the young tree to a tree stake.'],ex:'dig → place → backfill → water → support.'},
{id:'u2-sq1',u:2,topic:'Sequence',t:'write',mode:'para-instr-short',q:'Revision 2c: Add sequence words to the ordered printing steps.',info:'Open the document… / Choose Print… / Check the printer name… / Click Print… / Collect your pages…',model:['First, open the document on the campus computer. Next, choose Print from the document menu. Then, check the printer name and number of copies. After that, click Print and wait for the job to finish. Finally, collect your pages from the printer.'],check:['First, Next, Then, After that, Finally (sırayla)','Virgül sequence word\'den sonra','Imperative']},

// conclusion
{id:'u2-c1',u:2,topic:'Conclusion',t:'mc',q:'Which is a correct concluding sentence for an instruction paragraph?',opts:['Check your spelling before you give it to your teacher.','Finally, click Send.','In this way, your lab report will be clear and easy to follow.','Next, write the aim.'],a:2,ex:'Sonucu gösteriyor. A ve B yeni adım (hocanın düzelttiği hata).'},
{id:'u2-c2',u:2,topic:'Conclusion',t:'write',mode:'res',q:'Revision 3e: Concluding sentence. Result: the application is sent to the club.',info:'',model:['Your application is now sent to the club.','In this way, your application will reach the club.'],check:['Sonucu gösteriyor','Yeni adım YOK (imperative değil)']},
{id:'u2-c3',u:2,topic:'Conclusion',t:'mc',q:'"The concluding sentence tells the reader the ____." (Exercise 1 rule)',opts:['idea','task','result','order'],a:2,ex:'result'},

// rules gap
{id:'u2-r1',u:2,topic:'Rules',t:'gap',q:'Complete the rules (three options are extra).',text:'1. The topic sentence introduces the {0} and tells the reader that steps will follow. 2. The supporting sentences explain what to {1}. 3. Signalling words like first and next show the {2} of the steps. 4. Instructions include the {3} of a verb, such as open, write, or check. 5. The concluding sentence tells the reader the {4}.',bank:['result','do','base form','order','task','idea','past form','explain'],a:['task','do','order','base form','result'],ex:'Fazla seçenekler: idea, past form, explain.'},

// analysis
{id:'u2-a1',u:2,topic:'Analysis',t:'mc',q:'Yasmine\'s draft: "Writing a lab report. You should write the title first. You write the aim… Conclusion is at the end. Check your spelling before you give it to your teacher." How many checklist items are YES (TS, imperative, sequence words, useful detail, warning, result)?',opts:['0','2','4','6'],a:0,ex:'Hepsi NO. Hoca 6 maddenin hepsini düzeltti.'},
{id:'u2-a2',u:2,topic:'Analysis',t:'mc',q:'Password paragraph: "(6) Be careful not to use your name, birthday, or any common word…" is…',opts:['a major detail','a minor detail','a warning','a conclusion'],a:2,ex:'Be careful = warning.'},
{id:'u2-a3',u:2,topic:'Analysis',t:'mc',q:'Jamie\'s first reply: "First, open your email and write a message. Next, send it to the teacher. Check your file carefully. Use a clear subject line." What is the main problem?',opts:['No imperatives','Steps are in the wrong order (send before check / subject line) and important steps are missing','Too many details','It uses past simple'],a:1,ex:'"Send" adımı kontrol ve konu satırından önce geliyor. Dosya ekleme adımı da eksik.'},

// writing
{id:'u2-pw1',u:2,topic:'Paragraph writing',t:'write',mode:'parts-instr',q:'Revision 3: Write each part (join a club online).',info:'a. TS — join a university club online | a few simple steps<br>b. First step + detail — open the Clubs page | use your university account to log in<br>c. Middle step + check — choose a club and read its meeting information | make sure the meeting time fits your schedule<br>d. Final step — click Join / Apply and complete the short form<br>e. Concluding — the application is sent to the club',model:['a. You can join a university club online in a few simple steps.\nb. First, open the Clubs page and log in with your university account.\nc. Next, choose a club and read its meeting information. Make sure the meeting time fits your schedule.\nd. Finally, click "Join" or "Apply" and complete the short form.\ne. Your application is now sent to the club.'],check:['a: task + steps','b: First, + imperative + detail','c: Next/Then + Make sure… (ayrı cümle)','d: Finally,','e: sonuç, yeni adım yok']},
{id:'u2-pw2',u:2,topic:'Paragraph writing',t:'write',mode:'para-instr',q:'Revision 5: Write instructions for a classmate who needs to make a copy on the campus photocopier (7–9 sentences, ONE paragraph).',info:'Diagram: 1 Tap your student card → 2 Select "Copy" → 3 Place your document on the glass → 4 Choose the settings (Copies: 1, Colour / Black & White) → 5 Press "Start".<br><img src="files/photocopier.png" class="diagram" alt="photocopier diagram">',model:['Making a copy on the campus photocopier is easy if you follow a few simple steps. First, tap your student card on the card reader next to the machine. Next, select "Copy" on the touch screen. Then, open the lid and place your document face down on the glass. Make sure the paper is straight and in the top corner. After that, choose the number of copies and select colour or black and white. Finally, press the green "Start" button and wait for your copies. Now your copy is ready to use.'],check:['TS: task + steps will follow','5 adım mantıklı sırada','Imperative (base verb), "you should" yok','Sequence words (First, Next, Then, After that, Finally)','Useful details (where / which button / how many)','En az 1 warning/check (Make sure… / Be careful…)','Sonuç cümlesi: yeni adım yok','7–9 cümle, TEK paragraf','Yazım/noktalama']},
{id:'u2-pw3',u:2,topic:'Paragraph writing',t:'write',mode:'para-instr',q:'Unit Task: "How to pack your suitcase for a one-week international holiday" (6–8 sentences).',info:'Plan: title + TS → equipment → steps in order → warning → result.',model:['Packing your suitcase for a one-week international holiday is easy if you follow a few simple steps. First, check the weather at your destination and make a list of the clothes you need. Next, put heavy items, such as shoes, at the bottom of the suitcase. Then, roll your T-shirts and trousers to save space. After that, put your toothbrush and other small items in a separate bag. Make sure your liquids are less than 100 ml and in a clear plastic bag. Finally, put your passport and tickets in your hand luggage. Now your suitcase is ready for your trip.'],check:['TS','Imperatives','Sequence words','Useful details','Warning','Result','6–8 cümle']},
{id:'u2-pw4',u:2,topic:'Paragraph writing',t:'write',mode:'para-instr',q:'Unit Task: "How to take care of your skin" (6–8 sentences).',info:'',model:['Taking care of your skin is simple if you follow a few easy steps. First, wash your face with warm water and a mild cleanser every morning and evening. Next, dry your skin gently with a clean towel. Then, apply a small amount of moisturiser to clean, dry skin. After that, put on sunscreen before you go outside. Remember to apply it again every two hours on sunny days. Finally, drink enough water during the day. In this way, your skin will stay healthy and fresh.'],check:['TS','Imperatives','Sequence','Detail (how much / when)','Warning','Result']},

// ===================== UNIT 3 =====================
{id:'u3-o1',u:3,topic:'Orientation',t:'mc',q:'Which is the best orientation sentence?',opts:['Missing my exam.','I wake up late and run.','Last Monday, I missed my first midterm exam at AGÜ.','It was a bad day.'],a:2,ex:'when (Last Monday) + who (I) + what (missed my first midterm exam) + where (at AGÜ).'},
{id:'u3-o2',u:3,topic:'Orientation',t:'mc',q:'"Last Saturday, my best friend and I watched a football match at a stadium in Istanbul." — WHERE?',opts:['Last Saturday','my best friend and I','watched a football match','at a stadium in Istanbul'],a:3,ex:'where = at a stadium in Istanbul.'},
{id:'u3-o3',u:3,topic:'Orientation',t:'mc',q:'"On my first day at AGÜ, I could not find my classroom for almost an hour." — WHEN?',opts:['for almost an hour','On my first day','at AGÜ','I'],a:1,ex:'when = on my first day.'},
{id:'u3-o4',u:3,topic:'Orientation',t:'mc',q:'Is a feeling word (e.g. unforgettable, stressful) compulsory in the orientation?',opts:['Yes, always','No, it is optional','Only in diaries','Only in the reorientation'],a:1,ex:'"It is not compulsory, but the orientation can also show how the writer felt."'},
{id:'u3-o5',u:3,topic:'Orientation',t:'write',mode:'orient',q:'Revision 1a: Write an orientation sentence.',info:'Who: my dorm friends | When: last Friday | Where: the common room | What: a surprise farewell party',model:['Last Friday, my dorm friends organised a surprise farewell party in the common room.','Last Friday, my dorm friends had a surprise farewell party for me in the common room.'],check:['When (Last Friday)','Who (my dorm friends)','What (surprise farewell party)','Where (in the common room)','Past simple fiil','Sadece verilen bilgiler']},
{id:'u3-o6',u:3,topic:'Orientation',t:'write',mode:'orient',q:'Revision 1b: Write an orientation sentence.',info:'Who: my roommate and I | When: two weeks ago | Where: our dorm building | What: getting stuck in the lift',model:['Two weeks ago, my roommate and I got stuck in the lift in our dorm building.'],check:['When','Who','What (got stuck — past)','Where']},
{id:'u3-o7',u:3,topic:'Orientation',t:'write',mode:'orient',q:'Revision 1c: Write an orientation sentence.',info:'Who: I | When: last month | Where: a café near campus | What: a job interview',model:['Last month, I had a job interview at a café near campus.'],check:['When','Who','What','Where','Past simple (had)']},
{id:'u3-o8',u:3,topic:'Orientation',t:'write',mode:'orient',q:'Revision 1d: Write an orientation sentence.',info:'Who: my classmates and I | When: yesterday | Where: the bus stop | What: missing the last bus',model:['Yesterday, my classmates and I missed the last bus at the bus stop.'],check:['When','Who','What (missed)','Where']},
{id:'u3-o9',u:3,topic:'Orientation',t:'write',mode:'orient',q:'Revision 3a: Write the orientation.',info:'Who: Sylvia and two classmates | What: first volunteering day | When: last Saturday | Where: an animal shelter',model:['Last Saturday, Sylvia and two of her classmates had their first volunteering day at an animal shelter.'],check:['When','Who','What','Where','Past simple']},

// past simple
{id:'u3-p1',u:3,topic:'Past simple',t:'mc',q:'Which is correct?',opts:['I did not found my wallet.','I did not find my wallet.','I not found my wallet.','I didn\'t founded my wallet.'],a:1,ex:'did not + base verb.'},
{id:'u3-p2',u:3,topic:'Past simple',t:'mc',q:'Choose the correct past simple: "I ____ the dorm at 8:00."',opts:['leave','leaved','left','was leave'],a:2,ex:'leave → left (irregular).'},
{id:'u3-p3',u:3,topic:'Past simple',t:'mc',q:'Yasmine\'s draft "I wake up late. I run to the bus stop. The bus is late." — main problem?',opts:['No imperatives','Present tense instead of past simple','Too many time markers','No sequence words in steps'],a:1,ex:'woke / ran / was.'},
{id:'u3-p4',u:3,topic:'Past simple',t:'write',mode:'past',q:'Revision 2b: Rewrite the notes as past-simple sentences (4 sentences).',info:'I / leave / dorm / at 8:00 | bus / arrive / late | I / not have / enough time | I / feel / worried',model:['I left the dorm at 8:00. The bus arrived late. I did not have enough time. I felt worried.'],check:['left (irregular)','arrived (-ed)','did not have (did not + V1)','felt (irregular)','Büyük harf + nokta']},
{id:'u3-p5',u:3,topic:'Past simple',t:'match',q:'Match the base verb with its past form.',left:['go','feel','find','catch','think','bring'],right:['found','went','brought','felt','thought','caught'],a:[1,3,0,5,4,2],ex:'go-went, feel-felt, find-found, catch-caught, think-thought, bring-brought.'},
{id:'u3-p6',u:3,topic:'Past simple',t:'mc',q:'Past situation or feeling uses…',opts:['did + base verb','was / were','am / is / are','will be'],a:1,ex:'The room was empty. We were confused.'},

// time markers
{id:'u3-t1',u:3,topic:'Time markers',t:'gap',q:'Exercise 4: Choose a time marker for each gap (one extra).',text:'{0}, I waited calmly because I thought the lesson would begin soon. {1}, the lecturer started speaking French. {2}, I noticed that every student had a French textbook. I checked my timetable. {3}, I packed my bag and left quietly. {4}, I reached the correct classroom just before the lesson started.',bank:['At first','A few minutes later','Suddenly','After that','In the end','One day'],a:['At first','A few minutes later','Suddenly','After that','In the end'],ex:'Extra: One day.'},
{id:'u3-t2',u:3,topic:'Time markers',t:'gap',q:'Revision 2c: Add suitable time markers.',text:'{0}, I arrived at the sports centre for my first yoga class. I waited near Studio 2. {1}, a coach told me that the class was upstairs. I ran to the third floor. {2}, I opened the door and saw a dance class instead. I checked the schedule again. {3}, I found the correct room and joined the last twenty minutes.',bank:['First','A few minutes later','Then','Finally','Suddenly','One day'],a:[['First'],['A few minutes later','Then'],['Then','Suddenly'],['Finally']],ex:'Başlangıç → sonraki olay → sonraki → son olay. (At first / After that / In the end da kabul edilir.)'},
{id:'u3-t3',u:3,topic:'Time markers',t:'mc',q:'Which time marker introduces an UNEXPECTED moment?',opts:['First','Suddenly','In the end','After that'],a:1,ex:'Suddenly / Just then / When…'},
{id:'u3-t4',u:3,topic:'Time markers',t:'mc',q:'Which time marker shows the LAST event or result?',opts:['At first','A few minutes later','In the end','One morning'],a:2,ex:'Finally / In the end.'},
{id:'u3-t5',u:3,topic:'Time markers',t:'order',q:'Revision 2a: Put the events in order.',items:['I went to the library to print my assignment before class.','A few minutes later, I noticed that my student card was missing.','I checked my bag and pockets, but I could not find it.','Then, I walked back to the places I had visited that morning.','I finally found my student card under a chair near the library entrance.'],ex:'went → noticed → checked → walked back → found.'},
{id:'u3-t6',u:3,topic:'Time markers',t:'order',q:'A trip to the market — order.',items:['I decided to walk to the market to buy fruit for the weekend.','Halfway there, I checked my pockets and could not find my wallet.','I realised I had left my wallet at home and had to go back for it.','In the end, I arrived late, but I still found the freshest strawberries.'],ex:'Cevap anahtarı: decided=1, halfway=2, realised=3, in the end=4.'},
{id:'u3-t7',u:3,topic:'Time markers',t:'write',mode:'past',q:'Exercise 6: Write four sentences in time order (past simple + at least two time markers).',info:'9:00 arrive at the student centre for the club meeting | 9:05 open the meeting-room door — see an exam in progress | 9:06 feel embarrassed — apologise and close the door | 9:10 check the message — find the correct room upstairs',model:['At 9:00, I arrived at the student centre for the club meeting. A few minutes later, I opened the meeting-room door and saw an exam in progress. I felt embarrassed, so I apologised and closed the door. After that, I checked the message and found the correct room upstairs.'],check:['Past simple (arrived, opened, saw, felt, apologised, closed, checked, found)','≥2 time markers','Sıra doğru']},

// sensory
{id:'u3-s1',u:3,topic:'Show, don\'t tell',t:'match',q:'Match the feeling with the showing detail.',left:['I was embarrassed.','I was excited.','The street was crowded.','The bag was heavy.','She was angry.'],right:['She slammed the door and didn\'t say a word.','People bumped into each other, and I lost sight of my friend.','My face turned red and I looked down at my shoes.','I couldn\'t stop talking and my hands were shaking with energy.','My shoulders ached and I had to stop and rest twice.'],a:[2,3,1,4,0],ex:'1-c, 2-d, 3-b, 4-e, 5-a'},
{id:'u3-s2',u:3,topic:'Show, don\'t tell',t:'mc',q:'Which sentence SHOWS (not tells) nervousness?',opts:['I was very nervous.','I felt nervous and bad.','My voice cracked and my palms were sweaty.','Nervous was me.'],a:2,ex:'Duyguyu vücut tepkisiyle gösteriyor.'},
{id:'u3-s3',u:3,topic:'Show, don\'t tell',t:'write',mode:'show',q:'Revision 2d: Improve by showing the feeling.',info:'Telling: I was nervous before my presentation.',model:['My hands were shaking, and my heart was beating fast before my presentation.','My voice cracked and my palms were sweaty as I walked to the front of the class.'],check:['Duygu kelimesi (nervous) yerine detay','Görülen / duyulan / hissedilen bir şey','Past simple / past continuous']},
{id:'u3-s4',u:3,topic:'Show, don\'t tell',t:'write',mode:'show',q:'Telling → Showing',info:'Telling: It was a stormy afternoon.',model:['Dark clouds covered the sky, and heavy rain hit the windows.'],check:['Duyusal detay (see/hear)','Past simple']},
{id:'u3-s5',u:3,topic:'Show, don\'t tell',t:'write',mode:'show',q:'Revision 3c: Add a sensory or feeling detail.',info:'Major event: Sylvia walked a large dog called Max. | Feeling: excited | Detail: could not stop smiling',model:['Sylvia walked a large dog called Max, and she could not stop smiling the whole time.'],check:['Olay + detay','"could not stop smiling" kullanıldı','"excited" kelimesi yerine gösterme (ya da ikisi birlikte)']},
{id:'u3-s6',u:3,topic:'Show, don\'t tell',t:'mc',q:'Lab profile: "Quiet room; strange smell; worried → relieved". Which is the best sensory/feeling detail?',opts:['I was worried.','The room was silent, and a strange smell came from our container, so my hands started to shake.','Then I left.','The experiment was in a lab.'],a:1,ex:'Ses + koku + vücut tepkisi = show, don\'t tell.'},

// reorientation
{id:'u3-r1',u:3,topic:'Reorientation',t:'mc',q:'"Looking back, it was a strange way to start the morning." This reorientation is a…',opts:['Final feeling','Comment','Lesson learned'],a:1,ex:'Comment.'},
{id:'u3-r2',u:3,topic:'Reorientation',t:'mc',q:'"From then on, I always double-check the time." This is a…',opts:['Final feeling','Comment','Lesson learned'],a:2,ex:'Lesson learned.'},
{id:'u3-r3',u:3,topic:'Reorientation',t:'mc',q:'"I was exhausted, but I had never felt so happy." This is a…',opts:['Final feeling','Comment','Lesson learned'],a:0,ex:'Final feeling.'},
{id:'u3-r4',u:3,topic:'Reorientation',t:'mc',q:'"It was one of the most embarrassing days of my life." This is a…',opts:['Final feeling','Comment','Lesson learned'],a:1,ex:'Comment (cevap anahtarı).'},
{id:'u3-r5',u:3,topic:'Reorientation',t:'mc',q:'"I still laugh when I think about it." This is a…',opts:['Final feeling','Comment','Lesson learned'],a:0,ex:'Final feeling (cevap anahtarı).'},
{id:'u3-r6',u:3,topic:'Reorientation',t:'mc',q:'"Next time, I\'ll pack my bag the night before." This is a…',opts:['Final feeling','Comment','Lesson learned'],a:2,ex:'Lesson learned.'},
{id:'u3-r7',u:3,topic:'Reorientation',t:'match',q:'Match the situation with the best ending.',left:['I missed the bus and had to walk two miles to work.','I forgot my lines during the school play.','We got lost on our hike but found a beautiful view.','I studied the wrong chapter for the exam.'],right:['Even now, I laugh when I remember that day on stage.','It was a small mistake, but now I always check the topics twice.','My feet hurt all day, and now I always leave home early.','We were so tired, but the view made the whole day worth it.'],a:[2,0,3,1],ex:'1-c, 2-a, 3-d, 4-b'},
{id:'u3-r8',u:3,topic:'Reorientation',t:'mc',q:'Which is NOT a good reorientation?',opts:['It was a stressful moment, but I learned to charge my phone every night.','Then we went to a restaurant and ordered soup.','In the end, we laughed about our "rainy picnic".','I felt tired but proud of my first climb.'],a:1,ex:'Yeni olay ekliyor, reorientation olamaz.'},
{id:'u3-r9',u:3,topic:'Reorientation',t:'write',mode:'reo',q:'Revision 3d: Write the reorientation.',info:'Final idea: tired but proud; wants to volunteer again',model:['In the end, Sylvia felt tired but proud, and she decided to volunteer again soon.','Looking back, it was a tiring but wonderful day, and Sylvia wanted to volunteer again.'],check:['Final feeling (tired but proud)','Volunteer again fikri','Yeni olay YOK','Signal (In the end / Looking back / Overall)']},
{id:'u3-r10',u:3,topic:'Reorientation',t:'write',mode:'reo',q:'Write a reorientation.',info:'Event: My phone died right before an important call, so I had to borrow my neighbour\'s.',model:['It was a stressful moment, but I learned to charge my phone every night.'],check:['Feeling / comment / lesson','Yeni olay yok']},

// identify / rules
{id:'u3-g1',u:3,topic:'Recount basics',t:'gap',q:'Complete the rules.',text:'In a personal recount, writers share an experience from their {0}. At the beginning, they give who, when, and {1} it happened. In the middle, they explain what {2}, in the {3} it happened. Writers mainly use the {4} to describe completed actions, and words such as {5} to show it is their own experience.',bank:['own lives','where','happened','order','past simple','I and my','feelings','details'],a:['own lives','where','happened','order','past simple','I and my'],ex:'Exercise 3 cevap anahtarı.'},
{id:'u3-g2',u:3,topic:'Recount basics',t:'mc',q:'Text: "Tuesday, 15 October — I finally asked a question in class today…" Where can you read it?',opts:['a social media post','a diary entry','a message to a friend','a blog entry'],a:1,ex:'Tarih + kişisel düşünceler = diary.'},
{id:'u3-g3',u:3,topic:'Recount basics',t:'mc',q:'"@deniz.on.campus I tried the university climbing wall today! … #CampusLife #FirstTry" Where?',opts:['a diary entry','a social media post','an email','a lab report'],a:1,ex:'@ + hashtag = social media post.'},
{id:'u3-g4',u:3,topic:'Recount basics',t:'mc',q:'Why was Yasmine\'s party message better than Amina\'s?',opts:['It was shorter','It gave where, clear time order with time words, feelings, and an overall feeling at the end','It used present tense','It had no feelings'],a:1,ex:'Amina: when/where yok, sıra karışık, duygu yok, kapanış yok.'},
{id:'u3-g5',u:3,topic:'Recount basics',t:'mc',q:'Grand Bazaar recount: which sentence is the reorientation?',opts:['One day, I went to the Grand Bazaar with a friend to buy a gift for my mother.','My heart was beating fast, and my hands felt cold.','In the end, I found my friend waiting there.','It was an embarrassing but unforgettable afternoon.'],a:3,ex:'Son yorum.'},

// writing
{id:'u3-pw1',u:3,topic:'Paragraph writing',t:'write',mode:'para-recount',q:'Revision 5: Write a recount about a lab experiment that did not go as planned (6–8 sentences, ONE paragraph).',info:'Who: you and your lab partner | When: last semester, during a laboratory class | Where: university science laboratory<br>E1: prepare the equipment and begin | E2: add one of the materials; nothing happens | E3: check the instructions — used the wrong amount | E4: start again and get the expected result<br>Sensory/feeling: quiet room; strange smell; worried → relieved<br>Ending: stressful, but the mistake taught you to check instructions carefully.',model:['Last semester, my lab partner and I did an experiment that did not go as planned in the university science laboratory. First, we prepared the equipment and began the experiment. Then, I added one of the materials to the container, but nothing happened. The room was completely quiet, a strange smell filled the air, and my hands started to shake. A few minutes later, we checked the instructions again and realised that we had used the wrong amount. After that, we started the experiment again, and finally we got the expected result. I took a deep breath and smiled at my partner. Looking back, it was a stressful lesson, but the mistake taught me to check instructions carefully.'],check:['Orientation: who + what + when + where','Her olayın başında time marker','Olaylar doğru sırada','Past simple tutarlı','Sensory/feeling detail (show, don\'t tell)','Reorientation: yorum/duygu/ders, yeni olay yok','I/my tutarlı, tekrar yok','6–8 cümle, TEK paragraf','Yazım/noktalama']},
{id:'u3-pw2',u:3,topic:'Paragraph writing',t:'write',mode:'para-recount',q:'Revision 5 title: "A Group Project Deadline" (6–8 sentences).',info:'Kendi deneyimini (ya da hayal ettiğin bir deneyimi) şablonla yaz.',model:['Last month, my group and I almost missed the deadline for our history project in the university library. At first, everything seemed fine because we had a clear plan. Then, the night before the deadline, one member sent a message and said that his part was not ready. My heart was beating fast, and I kept looking at the clock on the wall. After that, we divided his part into three and worked until two o\'clock in the morning. Finally, we uploaded the project just ten minutes before the deadline. Looking back, it was a stressful night, but I learned to check my group\'s progress every week.'],check:['Orientation','Time markers','Past simple','Showing detail','Reorientation','6–8 cümle']},
{id:'u3-pw3',u:3,topic:'Paragraph writing',t:'write',mode:'para-recount',q:'Unit Task: "An unexpected surprise" (6–8 sentences).',info:'',model:['Last summer, my family gave me a surprise I will never forget at our home in Kayseri. At first, I thought it was a normal Sunday, and I was watching TV in the living room. Suddenly, the doorbell rang, and my mother asked me to open the door. When I opened it, I saw my best friend from Germany with a big smile and a heavy suitcase. My mouth fell open, and I could not say a word for a few seconds. After that, we hugged and talked for hours in the garden. Looking back, it was the happiest surprise of my life.'],check:['Orientation','Time markers','Past simple','Showing detail','Reorientation','6–8 cümle']},
{id:'u3-pw4',u:3,topic:'Paragraph writing',t:'write',mode:'para-recount',q:'Rewrite Yasmine\'s weak draft as a good recount.',info:'"Missing my exam. I wake up late. My alarm did not ring. I run to the bus stop. The bus is late. I am worried. I arrive at the classroom. The door is closed. I feel bad about it."',model:['Last Monday, I missed my first midterm exam at AGÜ. That morning, I woke up late because my alarm did not ring. First, I got dressed quickly and ran to the bus stop. Then I waited for the bus, but it was late. My heart was beating fast, and I kept looking at my watch. Finally, I arrived at the classroom, but the door was already closed. I learned an important lesson that day, and now I always set two alarms.'],check:['"Missing my exam." yerine tam orientation (when/where)','Hepsi past simple','Time markers','"I am worried" yerine showing','Reorientation: ders / yorum']}
];
